def count_m_n(p):
    N = len(p)
    m = 0
    n = 0
    for i in range(N):
        for j in range(i + 1, N):
            if p[j] == p[i] + 1:
                for k in range(j + 1, N):
                    if p[k] == p[j] + 1:
                        m += 1
                        for l in range(k + 1, N):
                            if p[l] == p[k] + 1:
                                n += 1
    return m, n

